/**
 * The contract `popover.tsx` (native) and `popover.web.tsx` (radix) both
 * implement. Its own module for the usual reason: Metro resolves `./popover`
 * to `popover.web.tsx` on web, so the web file cannot import shared types from
 * `./popover` without importing itself.
 *
 * Narrower than radix's props on purpose: a controlled popover, an `asChild`
 * trigger, and one content pane. That is the shape both platforms can honour —
 * everything radix offers beyond it (collision handling, side flipping, nested
 * anchors) has no native counterpart, so exposing it would be a promise only
 * one platform keeps.
 */
import type { ReactNode } from "react";

export type PopoverProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  children: ReactNode;
};

export type PopoverTriggerProps = {
  /**
   * Hand the press handler to the single child element rather than wrapping it.
   * Always pass it: a `Pressable` wrapping a `Button` never fires on native,
   * because the inner pressable claims the touch responder.
   */
  asChild?: boolean | undefined;
  children: ReactNode;
};

export type PopoverContentProps = {
  className?: string | undefined;
  /** Web only — the native sheet is centred and has nothing to align to. */
  align?: "start" | "center" | "end" | undefined;
  children?: ReactNode;
};

/**
 * The native popover: a transparent `Modal` with a dimmed backdrop and a
 * centred card.
 *
 * It is deliberately *not* anchored to its trigger. Anchoring means measuring
 * the trigger and flipping the card against the viewport, which is a chunk of
 * layout code to reproduce a hover-era affordance — on a phone a centred sheet
 * is the native idiom anyway. `align` is accepted and ignored, and the same
 * backdrop-as-sibling rule as `dialog.tsx` applies (a `Pressable` has no
 * `stopPropagation`, so the card must not be nested inside it).
 */

import { cloneElement, createContext, isValidElement, type ReactElement, useContext } from "react";
import { Modal, Pressable, View } from "react-native";
import type {
  PopoverContentProps,
  PopoverProps,
  PopoverTriggerProps,
} from "@/components/ui/popover-base";
import { cn } from "@/lib/utils";

type PopoverState = { open: boolean; setOpen: (open: boolean) => void };

const PopoverContext = createContext<PopoverState>({
  open: false,
  setOpen: () => {},
});

function Popover({ open, onOpenChange, children }: PopoverProps) {
  return (
    <PopoverContext.Provider value={{ open, setOpen: onOpenChange }}>
      {children}
    </PopoverContext.Provider>
  );
}

function PopoverTrigger({ asChild, children }: PopoverTriggerProps) {
  const { setOpen } = useContext(PopoverContext);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onPress?: () => void }>, {
      onPress: () => setOpen(true),
    });
  }
  return (
    // The `role` is hand-written because a `<button>` has no native counterpart.
    <Pressable role="button" onPress={() => setOpen(true)}>
      {children}
    </Pressable>
  );
}

function PopoverContent({ className, children }: PopoverContentProps) {
  const { open, setOpen } = useContext(PopoverContext);
  return (
    <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
      <View className="flex-1 items-center justify-center bg-black/60 p-6">
        <Pressable
          className="absolute inset-0"
          onPress={() => setOpen(false)}
          role="button"
          aria-label="Close"
        />
        <View className={cn("w-72 rounded-md border border-border bg-popover p-4", className)}>
          {children}
        </View>
      </View>
    </Modal>
  );
}

export { Popover, PopoverContent, PopoverTrigger };

/**
 * The web popover: radix, anchored to its trigger. `popover.tsx` is the native
 * counterpart and `popover-base.ts` holds the contract they share.
 */

import { Popover as PopoverPrimitive } from "radix-ui";
import type {
  PopoverContentProps,
  PopoverProps,
  PopoverTriggerProps,
} from "@/components/ui/popover-base";
import { cn } from "@/lib/utils";

function Popover({ open, onOpenChange, children }: PopoverProps) {
  return (
    <PopoverPrimitive.Root open={open} onOpenChange={onOpenChange}>
      {children}
    </PopoverPrimitive.Root>
  );
}

function PopoverTrigger({ asChild, children }: PopoverTriggerProps) {
  return <PopoverPrimitive.Trigger asChild={asChild ?? false}>{children}</PopoverPrimitive.Trigger>;
}

function PopoverContent({ className, align = "center", children }: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        align={align}
        sideOffset={4}
        className={cn(
          "z-50 w-72 rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
          className,
        )}
      >
        {children}
      </PopoverPrimitive.Content>
    </PopoverPrimitive.Portal>
  );
}

export { Popover, PopoverContent, PopoverTrigger };
